arguments.file_text:
@page "/chat"
@namespace sv_3777c1a45ecb41c3b169696dfa644594.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@ActiveChannelName"
                 ChannelDescription="@ActiveChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadOlderMessages"
                 class="@(threadOpen ? "with-thread" : "full-width")" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private List<Message> threadReplies = new();
    private Message? threadRootMessage;

    private int activeChannelId;
    private bool threadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    private string ActiveChannelName =>
        channels.FirstOrDefault(c => c.Id == activeChannelId)?.Name ?? "";

    private string ActiveChannelDescription =>
        channels.FirstOrDefault(c => c.Id == activeChannelId)?.Description ?? "";

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;
        threadSummaries = BuildThreadSummaries(messages);
        await ChatService.MarkChannelReadAsync(channelId);
        CloseThread();
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            threadSummaries = BuildThreadSummaries(messages);
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        threadSummaries = BuildThreadSummaries(messages);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messageSkip);
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> msgs)
    {
        // Build thread summaries from messages that have replies
        var rootIds = msgs
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
        return rootIds;
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #34373c;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-desc {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    min-width: 0;
}

.message-area.full-width {
    flex: 1;
}

.message-area.with-thread {
    flex: 0 0 55%;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #8e9297;
    font-size: 0.85rem;
}

/* Message Bubble */
.message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    margin-bottom: 4px;
    position: relative;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
